import {
  AnimationSpec,
  BackgroundType,
  CameraMove,
  CharacterAction,
  CharacterExpression,
  COMPOSITION_DEFAULTS,
  SceneElement,
  SpecTiming,
  TextAnimation,
} from './types';

/**
 * Runtime validation for animation specs.
 *
 * A spec is generated by a language model, so it is untrusted input: every field the renderer relies
 * on is checked here and failures are reported as readable strings instead of crashing mid-render with
 * "cannot read property of undefined" 4,000 frames into a build.
 */

const BACKGROUNDS: BackgroundType[] = [
  'dusk_room',
  'twilight_skyline',
  'floating_staircase',
  'dome_interior',
  'open_horizon',
];
const CAMERAS: CameraMove[] = ['static', 'slow_zoom_in', 'slow_zoom_out', 'pan_up', 'pan_down'];
const ACTIONS: CharacterAction[] = ['idle', 'panicked'];
const EXPRESSIONS: CharacterExpression[] = ['neutral', 'shocked', 'happy'];
const ANIMATIONS: TextAnimation[] = ['spring_pop', 'fade', 'slide_up'];
const BUNDLED_FONTS = ['StudioSans', 'StudioSansBold', 'StudioMono'];

export type ValidationResult =
  | { ok: true; spec: AnimationSpec; timing: SpecTiming; warnings: string[] }
  | { ok: false; errors: string[]; warnings: string[] };

const isHex = (value: unknown): boolean =>
  typeof value === 'string' && /^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.test(value);

const isNumber = (value: unknown): value is number =>
  typeof value === 'number' && Number.isFinite(value);

/** Sum scene durations and derive composition timing. */
export const timingFor = (spec: AnimationSpec): SpecTiming => {
  const sceneStarts: number[] = [];
  let cursor = 0;
  for (const scene of spec.scenes) {
    sceneStarts.push(cursor);
    cursor += scene.durationFrames;
  }
  return {
    fps: spec.fps ?? COMPOSITION_DEFAULTS.fps,
    width: spec.width ?? COMPOSITION_DEFAULTS.width,
    height: spec.height ?? COMPOSITION_DEFAULTS.height,
    durationInFrames: cursor,
    sceneStarts,
  };
};

const validateElement = (element: SceneElement, where: string, errors: string[]): void => {
  if (!element || typeof element !== 'object') {
    errors.push(`${where}: element is not an object`);
    return;
  }
  switch (element.type) {
    case 'character':
      if (!isNumber(element.x) || !isNumber(element.y)) errors.push(`${where}: character needs numeric x and y`);
      if (element.action && !ACTIONS.includes(element.action)) errors.push(`${where}: unknown action "${element.action}"`);
      if (element.expression && !EXPRESSIONS.includes(element.expression))
        errors.push(`${where}: unknown expression "${element.expression}"`);
      if (element.scale !== undefined && !isNumber(element.scale)) errors.push(`${where}: scale must be a number`);
      break;
    case 'text_overlay':
      if (typeof element.text !== 'string' || element.text.trim() === '')
        errors.push(`${where}: text_overlay needs non-empty text`);
      if (!isNumber(element.x) || !isNumber(element.y)) errors.push(`${where}: text_overlay needs numeric x and y`);
      if (element.animation && !ANIMATIONS.includes(element.animation))
        errors.push(`${where}: unknown text animation "${element.animation}"`);
      break;
    case 'hud_chip':
      if (typeof element.label !== 'string' || typeof element.value !== 'string')
        errors.push(`${where}: hud_chip needs string label and value`);
      if (!isNumber(element.x) || !isNumber(element.y)) errors.push(`${where}: hud_chip needs numeric x and y`);
      break;
    case 'fracture':
      if (typeof element.path !== 'string' || !element.path.trim().startsWith('M'))
        errors.push(`${where}: fracture path must be an SVG path string starting with "M"`);
      if (element.strokeWidth !== undefined && !isNumber(element.strokeWidth))
        errors.push(`${where}: fracture strokeWidth must be a number`);
      break;
    case 'particles':
      if (element.count !== undefined && (!isNumber(element.count) || element.count < 0))
        errors.push(`${where}: particles count must be a non-negative number`);
      break;
    case 'glow':
      if (!['x', 'y', 'width', 'height'].every((key) => isNumber((element as Record<string, unknown>)[key])))
        errors.push(`${where}: glow needs numeric x, y, width and height`);
      break;
    default:
      errors.push(`${where}: unknown element type "${(element as { type?: string }).type}"`);
  }
};

/**
 * Validate an unknown value (typically `JSON.parse`d model output) and return the typed spec plus its
 * derived timing, or a list of everything that is wrong with it.
 */
export const validateSpec = (input: unknown): ValidationResult => {
  const errors: string[] = [];
  const warnings: string[] = [];

  if (!input || typeof input !== 'object') {
    return { ok: false, errors: ['spec is not an object'], warnings };
  }
  const spec = input as AnimationSpec;

  if (typeof spec.title !== 'string' || spec.title.trim() === '') errors.push('title is required');
  if (typeof spec.slug !== 'string' || !/^[a-z0-9][a-z0-9-]*$/.test(spec.slug))
    errors.push('slug is required and must be lowercase kebab-case (e.g. "what-if-moon")');

  if (!spec.theme || typeof spec.theme !== 'object') {
    errors.push('theme is required');
  } else {
    if (!isHex(spec.theme.primaryColor)) errors.push('theme.primaryColor must be a hex colour');
    if (!isHex(spec.theme.secondaryColor)) errors.push('theme.secondaryColor must be a hex colour');
    if (spec.theme.accentColor !== undefined && !isHex(spec.theme.accentColor))
      errors.push('theme.accentColor must be a hex colour');
    if (spec.theme.fontFamily && !BUNDLED_FONTS.includes(spec.theme.fontFamily))
      warnings.push(
        `fontFamily "${spec.theme.fontFamily}" is not bundled; the renderer falls back to ${BUNDLED_FONTS[1]}`,
      );
  }

  if (!Array.isArray(spec.scenes) || spec.scenes.length === 0) {
    errors.push('scenes must be a non-empty array');
  } else {
    const seen = new Set<string>();
    spec.scenes.forEach((scene, index) => {
      const where = `scenes[${index}]`;
      if (!scene || typeof scene !== 'object') {
        errors.push(`${where}: not an object`);
        return;
      }
      if (typeof scene.id !== 'string' || scene.id.trim() === '') errors.push(`${where}: id is required`);
      else if (seen.has(scene.id)) errors.push(`${where}: duplicate id "${scene.id}"`);
      else seen.add(scene.id);

      if (scene.type !== 'vector_environment')
        errors.push(`${where}: type must be "vector_environment" (got "${scene.type}")`);
      if (!BACKGROUNDS.includes(scene.background))
        errors.push(`${where}: unknown background "${scene.background}" (one of ${BACKGROUNDS.join(', ')})`);
      if (!isNumber(scene.durationFrames) || scene.durationFrames <= 0)
        errors.push(`${where}: durationFrames must be a positive number`);
      if (scene.camera && !CAMERAS.includes(scene.camera))
        errors.push(`${where}: unknown camera move "${scene.camera}"`);
      if (!Array.isArray(scene.elements)) errors.push(`${where}: elements must be an array`);
      else scene.elements.forEach((element, elementIndex) => validateElement(element, `${where}.elements[${elementIndex}]`, errors));
    });
  }

  if (!Array.isArray(spec.narration)) {
    errors.push('narration must be an array');
  } else {
    spec.narration.forEach((cue, index) => {
      if (!cue || typeof cue.text !== 'string') errors.push(`narration[${index}]: text is required`);
      else if (!isNumber(cue.frameStart) || cue.frameStart < 0)
        errors.push(`narration[${index}]: frameStart must be a non-negative number`);
    });
  }

  if (errors.length > 0) return { ok: false, errors, warnings };

  const timing = timingFor(spec);
  if (spec.totalDurationFrames !== undefined && spec.totalDurationFrames !== timing.durationInFrames) {
    warnings.push(
      `totalDurationFrames (${spec.totalDurationFrames}) does not match the sum of scene durations (${timing.durationInFrames}); the sum wins`,
    );
  }
  const lastCue = spec.narration.reduce((max, cue) => Math.max(max, cue.frameStart), 0);
  if (lastCue >= timing.durationInFrames) {
    warnings.push(`narration cue at frame ${lastCue} is past the final frame (${timing.durationInFrames - 1})`);
  }

  return { ok: true, spec, timing, warnings };
};

/** Validate and throw — for build-time imports where a bad spec should fail loudly. */
export const assertSpec = (input: unknown): { spec: AnimationSpec; timing: SpecTiming } => {
  const result = validateSpec(input);
  if (!result.ok) {
    throw new Error(`Invalid animation spec:\n- ${result.errors.join('\n- ')}`);
  }
  return { spec: result.spec, timing: result.timing };
};
